#!/bin/bash
# Generates one debugger script per test case into faelle/ (one guest boot per case, so a wedged tty cannot
# spoil the next case).  Run: gen_faelle.sh   then   alle.sh WORKDIR
cd "$(dirname "$0")"; mkdir -p faelle; rm -f faelle/*.dbg
LOGS='lp <<0>>%087A [SP+2]w [SP+4]w
lp <<0>>%0B6E [SP+2]w [SP+4]w
lp <<0>>%0C7C
lp <<0>>%0D56
lp <<0>>%48C4 [SP+2]w
lp <<0>>%3630
lp <<0>>%35AE [SP+2]w [SP+4]w
lp <<0>>%4BD0 [SP+2]w'
# common start: a fresh "cat" is stopped at its first user instruction (PC 0 in segment 1..3, user FCW)
start() { # file, title
cat > "$1" <<EOT
# $2   (generated by gen_faelle.sh)
# Kernel entries logged at function entry ([SP+2]w/[SP+4]w = first two arguments):
# 087A trap(dev,ident)  0B6E psignal(p,sig)  0C7C psig  0D56 core  48C4 exit(rv)  3630 sigret  35AE sendsig(p,n)  4BD0 sbreak
# Kernel data: u at FC00 in segment 0 (raw cells em:0FC00..), u_dsize FCAA, u_signal[n] FCD2+2n.
cpu u8000
trap clear
b <<1>>%0000
b <<2>>%0000
b <<3>>%0000
keys cat\\r
g 60000000
r
bd <<1>>%0000
bd <<2>>%0000
bd <<3>>%0000
EOT
}
finish() { # file, [stop offset]
{ [ -n "$2" ] && for s in 1 2 3; do echo "b <<$s>>%$2"; done
echo "$LOGS"
echo "g 400000000"; } >> "$1"
}
fin_tail() {
cat >> "$1" <<EOT
r
lpl
trap 3
screen
q
EOT
}
priv() { # name, poke
f=faelle/v2_$1.dbg; start $f "V2 $1: overwrite the first user instruction of cat with a privileged instruction"
case $1 in
SC_40) echo "d %FFB0 32" >> $f; echo "x/8xw SP" >> $f; echo "set R2 %FFBE" >> $f ;;
esac
echo "$2" >> $f; echo "u %0000 2" >> $f
case $1 in
SC_20|SC_3F|SC_FF) # invalid number: look at the user state right behind the SC (R4 = error code, carry flag in FCW)
  echo "e %0002 7F 01" >> $f; finish $f 0002; echo "r" >> $f; echo "g 1500000000" >> $f ;;
*) finish $f; echo "g 1500000000" >> $f ;;
esac
fin_tail $f
}
priv DI "e %0000 7C 00"
priv HALT "e %0000 7A 00"
priv IN "e %0000 3B 04 00 80"
priv OUT "e %0000 3B 06 00 80"
priv LDCTL_R0_FCW "a %0000 ldctl r0,fcw"
priv LDCTL_FCW_R0 "a %0000 ldctl fcw,r0"
priv IRET "e %0000 7B 00"
priv SC_20 "e %0000 7F 20"
priv SC_3F "e %0000 7F 3F"
priv SC_FF "e %0000 7F FF"
priv SC_40 "e %0000 7F 40"
sig() { # name, SP
f=faelle/v3_sig_$1.dbg; start $f "V3a signal delivery with user SP=$1: SIGINS handler (u_signal[4]=0200, handler = SC #1) then DI at PC 0"
cat >> $f <<EOT
d em:0FCD2 16
e em:0FCDA 02 00
d em:0FCD2 16
e %0200 7F 01
e %0000 7C 00
set R15 %$1
d %FFE0 32
d %0000 16
r
EOT
finish $f 0200
cat >> $f <<EOT
# --- stop at the handler (or elsewhere)
r
x/4xw SP
d %FFE0 32
d %0000 16
g 1500000000
r
lpl
trap 3
screen
q
EOT
}
sig 0000; sig 0008; sig 0004
brk() { # name, R0, SP
f=faelle/v3_brk_$1.dbg; start $f "V3b brk(R0=$2) via SC #17 at PC 0 (SP=${3:-unchanged}); exit via SC #1 at PC 2"
cat >> $f <<EOT
e %0000 7F 11
e %0002 7F 01
set R0 %$2
EOT
[ -n "$3" ] && cat >> $f <<EOT
set R15 %$3
e %$3 77 77 77 77 77 77 77 77
d %$3 16
EOT
cat >> $f <<EOT
d em:0FCA8 8
d %FEF0 32
r
EOT
finish $f 0002
cat >> $f <<EOT
# --- stop behind the SC (or elsewhere)
r
d em:0FCA8 8
d %FEF0 32
d %FE80 16
g 1500000000
lpl
trap 3
screen
q
EOT
}
brk FF00 FF00; brk FF01 FF01; brk FFFF FFFF; brk 0100 0100; brk FF00_SPFE80 FF00 FE80
ls faelle | wc -l
